/**
 * Just say hello.
 * @param {object} query query parameter(but not use).
 */
function sayHello(query) {
    return new Promise((resolve) => {
        resolve({
            message:'Hello World',
            date_time: (new Date()).toISOString() 
        });
    });
}

/**
 *  Just Return what server have got.
 * @param {object} request_body_json request body json
 */
function echo(request_body_json) {
    return new Promise((resolve) => {
        resolve(request_body_json);
    });
}


const Server = require('../index');

var server = new Server(8080);

server.addAPI('/hello', 'GET', sayHello)
    .addAPI('/echo', 'POST', echo)
    .start();
